    "referenceAnswer": "可選希望灌注、普同感、資訊傳遞、人際學習、團體凝聚力。希望：同儕分享戒用的小進步，增加改變期待；普同：知道羞恥與誘惑並非獨有，減少孤立；資訊：提供成癮與求助知識，辨識錯誤訊息；人際學習：在此時此地演練拒絕邀用並收回饋；凝聚力：穩定保密規範與互助，支援八週持續參與。每項均說明概念及對10名15至18歲成員的需求。八週90分鐘是設計背景，題目核心是五因子的適配理由；其他五項組合有合理論證也可。醫療風險與戒斷交由醫療評估，不由團體取代。",
