      "工作者守約尊重並肯定合法行為，不增強犯罪合理化；",
      "共同確定個案重視且可處理的問題、設定目標、拆解步驟與追蹤；",
      "以同理、真誠與可靠性建立合作。",
      "例：把就業與減少違規連結，邀個案選職訓、陪同連結並記錄進度。",
