    "referenceAnswer": "五種團體獨特力量可列多元互動與回饋、社會縮影、替代學習與榜樣、互助及歸屬、現場行為練習；分別幫助即將假釋者瞭解互動模式、練習拒絕犯罪邀約與求助。五療效因子可選希望、普同、利他、人際學習、凝聚，說明看見成功、減少羞恥、貢獻價值、反饋修正和互助承諾。二清單可有機制交疊，但須分別五項與假釋復歸連結，不能把經濟性等同療效因子。具體訂就業、家庭溝通及風險情境計劃，建立出監後支援。",
