    "questionId": "監獄官-108-諮商與矯正輔導-3",
    "referenceAnswer": "酒精使用障礙為使用模式造成顯著損害或痛苦，12個月內11項中至少2項；重度至少6項。可列六症狀：量或時間超過預定、想減卻失敗、大量時間取得使用恢復、渴求、重要責任失敗、明知人際問題仍使用；另有放棄活動、危險使用、明知身心問題續用、耐受、戒斷。戒斷在減停長期大量使用後可見自律神經亢進、手抖、失眠、噁心嘔吐、短暫幻覺／錯覺，另可焦慮、精神動作激動、全身性癲癇。列五即可，但重症戒斷需醫療處置，不能單靠意志。",
