      "AL主要青春期出現，生物成熟與成人社會地位之成熟鴻溝，模仿同儕以取得成人象徵，成人角色開放後多中止，但犯罪後果可困住部分人。",
      "比例不可把男性樣本分母當總人口，亦不可把少數LCP與多數AL硬分成全部人口兩群；",
