    "questionId": "監獄官-115-犯罪學與再犯預測-1",
    "referenceAnswer": "中止是過程，影響含社會連結與工作家庭轉折、日常結構、能動選擇、年齡及累積機會，亦重Maruna贖回故事與守法認同、他人認可。Maguire／Raynor提醒復歸資源和個人動機互動，不能只靠風險分數。Bucklen倡支援認同轉變、關係與優勢、現實社會資本、與當事人合作目標、減少不必要制度障礙，並衡量漸進改變而非一次違犯全盤否定。監所可建合法工作技能、家庭關係、同儕導師、責任與出監暖轉介，持續追蹤；婚姻就業不是機械保證。",
