    "referenceAnswer": "RANT是藥物相關司法個案早期分流的簡短工具，分別辨識在通常司法介入中失敗的風險與臨床／治療需求，形成高風險高需求、高風險低需求、低風險高需求、低風險低需求四類。前者可配較密監督與治療，高風險低需求重監督／行為，低風險高需求重醫療而避免過度司法，低低配低強度適當服務。原始研究19項，不是完整診斷或自動決定判刑；需受訓、在本地驗證與複評，臨床需求及再犯風險不可混為同一軸。",
