    "questionId": "監所管理員-115-犯罪學概要-3",
    "referenceAnswer": "大規模殺人通常指同一事件或相近時空內殺害多人，數字門檻依研究及法律定義不同；美國聯邦部分定義用三人，舊犯罪學常用四人，須註明版本。連續殺人依FBI2005共識為同一人或多人在不同事件非法殺害兩名或以上，重點是分開的事件，不必死守舊三人或長冷卻期。區分事件數、時空與歷程，不能以動機或精神疾病一概分類；spree等其他分類另須說明。題無指定門檻時接納有來源且一致的定義。",
