    "questionId": "監所管理員-111-犯罪學概要-1",
    "referenceAnswer": "Miller下階層焦點關切常列麻煩、強硬、機靈、刺激、命運、自主；少年透過團體表現強悍、避權威與尋刺激，在主流法規範中可能衝突。理論強調既存文化生活關切，不同於Cohen地位挫折的反主流反應。每項解釋，如機靈為佔便宜與不受騙、自主為拒控制。歷史研究與階級概括有偏差，不能把所有低收入者當同文化或必然犯罪，防治須提供合法地位機會與支援。",
