    "referenceAnswer": "Loeber三路徑：公開路徑由輕微攻擊到打架、嚴重暴力；隱蔽路徑由輕微偷竊／說謊到財物破壞及較嚴重財產犯罪；權威衝突由固執到公然違抗、逃避權威如逃學離家。路徑可重疊、不是人人按相同階段升級；縱貫研究用於早期辨識與適齡支援，不是將小錯必然預測重大犯罪。須看行為持續、家庭學校與保護因素，避免只以逃學刑事化。",
