    "referenceAnswer": "控制模式強調秩序、安全與集中權威，生活高度規定、較少自主，對非正式團體與幫派嚴控，避免其替代正式權力。責任模式重參與、自律與合作，使受刑人承擔較多日常選擇，善用合法團體與溝通，但幫派暴力仍須制止。依三軸比較管理哲學、生活自由、團體態度，而非責任模式放任幫派或控制模式不需處遇。歷史州別為典型而非今日所有設施統一；實際需兼顧安全、權利與環境適配，本題歷史版本仍需教材核對。",
