    "referenceAnswer": "封城減少公共活動與目標暴露、增加住家守護，可降低某些街頭搶竊；居家同處、隔離支援與守護不足可能提高家暴，線上娛樂和交易提高網路目標接觸。GST說明失業、財務、自由受限與健康壓力引起負向情緒，在資源不足時可能以暴力或詐騙因應。兩論分別解釋機會與動機，可整合但不推所有國家同方向。統計須留意低報、報案渠道與罪型差異，不能把通報下降等同真實傷害下降。",
