      "戊行為17，偵查終結20若原未依法經少年法院移送，檢察官應補循少年程序，再依27第1項第2款處理，不自行取代法院。",
      "各年齡採用時點須說明，刑法不罰與保護處理不同，舊兒童管轄規定不混用。"
