    "questionId": "110-刑法-3",
    "referenceAnswer": "甲事故傷人離去涉現行185之4，即使無過失也屬構成、依第2項減免；有人救助不當然等於已完成身份救護義務，需看是否有逃逸故意。乙0.23未達0.25仍可依185之3第1項第2款外觀不能安全駕駛，走不直與語亂為證；事故因果另查。丙假冒駕駛幫助犯人隱避可164，夫妻167可減免非當然無罪；被告式說謊非168，須區別僅虛假陳述與有妨逃功能。本站不沿舊無過失肇逃全免結論。",
