    "referenceAnswer": "警依法臨檢蒐證中甲強暴，135妨公；現行對依法執行公權力公務員加重等條款按事實核對。左眼0.1且只能50公分是否嚴重減損視能依10第4項臨床功能判，不能僅一數自動，但題重損支援重傷。甲有傷害故意、重傷可預見可277致重傷，若重傷故意278；與135加重結果需要因果與預見，非把所有揮拳視故意重傷。拒酒測本身行政與刑事酒駕分開，數罪競合說明。",
