    "referenceAnswer": "21調查官必要可通知法定代理父丙到場、依法記載簽名送達且通知輔佐；丙合法傳喚無正當不到，乙應請少年法官依22發同行書，不能自己簽發強制同行。23由執達員／司法警察執行並注意身名、三聯交付與記錄；須先核送達和不到理由。丙是法定代理而非一般證人任意拘提，少年保護者亦在適用範圍，權利與比例維護，乙調查許可權不等於裁判拘束許可權。",
