    "referenceAnswer": "攜可供威脅人安全鐵錘涉321兇器加重竊盜，敲窗探入已對財物佔有造成直接危險，依主觀客觀標準可著手未遂321第2項／25；車輛不是住宅，不一律侵入住宅加重。車窗毀損354已既遂，毀損作竊手段是否想像／實質競合看行為關係，不能說未偷到就只毀損。兇器不需本次打人，但須具有危險且知攜，沒收工具須所有與比例。",
