    "referenceAnswer": "168偽證須在法院審判或檢察官偵查依法具結、對重要事項虛假陳述。檢察事務官詢問丙不等同有檢察官合法命具結，題沒具結事實故通常不成168；好友也非法定身分拒證當然理由，若將來合法具結須誠實或依法拒證。僅「沒看到」口供不當然165湮滅物證或164隱避，需獨立構成。區別道德說謊與刑法明文，不憑維護朋友推所有妨害司法罪。",
