    "referenceAnswer": "甲公務員違法搜尋137須真的實施違授權搜尋，刑訴131之1同意須自願、權人、證件告知與記錄等，丙讓進入可為同意但不能只有默許認自願全部搜查。未持票不自動犯罪，須法律強制搜尋例外與主觀違法故意；合法同意範圍內不成137、306。若以虛假權力強迫同意或超範圍搜，可能137及其他侵入，不能找不到乙倒推搜尋合法／非法。服務證說明是程序之一非免票充分理由。",
