    "referenceAnswer": "甲為性交先撞倒乙，故意傷害且有生命危險可殺人間接故意須證；企圖脫衣性交已著手，依221強制性交未遂，利用自己暴力造成昏迷通常不轉成較輕單純225。甲先危險與承諾送醫排除其他救助15保證人，知不救必死卻繞行可不作為殺人既遂，鑑定即送不會死支援準因果。226之1強制性交而故意殺人結合犯的範圍包括未遂性交、獨立傷害與剝自由競合須論。不能只按276過失或強制性交既遂填入無性交事實。",
