    "questionId": "薦任升等（矯正）-112-刑法-4",
    "referenceAnswer": "乙受託持有甲禮金3200，抽1200據為己有以送己禮，335侵佔既遂；為自己或第三人所有意圖，不因剩餘仍送新人而消失。雖乙公務員，但私人代交婚禮紅包非職務持有，不成336公務侵佔；是否業務持有須工作性質而非受託一次。竊盜要求破持有，本案先有合法持有故區別。損害新人或甲與財物歸屬須明，沒收1200或價額與返還核對，不能先論公務員必貪汙。",
