      "若有具體危害安全秩序風險，只能採最小必要範圍並敘明理由，保留原文及提供異議救濟；",
      "寄送出版文稿另涉及言論與出版自由。",
      "保安25仍須作合憲限縮，不能把機關不喜歡的內容當紀律危害；",
      "該解釋原標的為監獄制度，應明示參照而非稱直接宣告25無效。"
