    "questionId": "109-刑事訴訟法與保安處分執行法-3",
    "referenceAnswer": "雖無罪主文有利，監護仍實質限制人身自由，甲對該不利處分有救濟利益，可就監護部分依法上訴，不因形式稱無罪就失去救濟。應依348確認宣告與有關係部分範圍，審查19責任能力、87具體危險必要及期間；精神鑑定只是證據，不代替法院判斷。甲不能只說身體健康便證明無危險，應提出醫療評估、治療成效及較小侵害替代方案。若題幹處分實際為另行裁定，則辨抗告程序；救濟形式依裁判性質，不能一律說上訴或一律不得。",
