    "questionId": "110-心理測驗員-心理學-2",
    "referenceAnswer": "知覺恆常性使距離、光線變動下仍辨識大小、形狀與顏色；完形接近、相似、連續、閉合及圖地原則組織訊息。映象神經元在特定動作執行與觀察中反應，可能參與動作理解，但不能視為所有同理心的已證實單一機制。功能預示性是環境相對個體能力提供的行動可能，如椅子可坐；前兩者支援環境辨認，後兩者連結行動及互動。",
