    "questionId": "109-心理測驗員-心理學-2",
    "referenceAnswer": "社會學習可選正向同儕榜樣、示範拒絕暴力及合作，讓學生觀察後演練並獲適當增強；避免讓偏差炫耀得到群體注意。認知行為可辨識敵意歸因與自動想法，以證據檢驗、問題解決及情緒技能建立替代反應。家校一致支援、追蹤事件與學生回饋，依需要調整；不把懲罰或宣導當作全部輔導。",
