    "questionId": "108-心理測驗員-心理學-1",
    "referenceAnswer": "遺忘可能來自登入不足、提取線索不合、前攝與倒攝幹擾，以及記憶隨時間與使用改變；不能單由「想不起」證明記憶已完全消失。前攝是舊知妨礙新知，倒攝是新知妨礙舊知。它可能影響學習、工作與安全，也可減少無關訊息負擔；用間隔回想、組織與情境線索改善，病理性記憶下降則須評估。",
